    public void UpdateJson(string json){var data=Data.Serializer.DeserializeObject(json);var rows=Data.List(Data.Get(data,"accounts"));SetBotStatus(rows.Any(a=>Data.S(a,"status")=="conectada")?"ONLINE":rows.Any(a=>Data.S(a,"status")=="conectando"||Data.S(a,"status").Contains("reconexão"))?"CONECTANDO":"OFFLINE");var runtime=Data.Get(data,"runtime");processLabel.Text=runtime==null?"":"Node · "+Data.N(runtime,"memoryMb").ToString("0.0")+" MB\nCPU Node · "+Data.N(runtime,"cpuPercent").ToString("0.0")+"%";accounts.Clear();foreach(var a in Data.List(Data.Get(data,"accounts")))accounts[(int)Data.N(a,"slot")]=a;logs=Data.List(Data.Get(data,"log")).ToList();Render();}
    public void SetNotice(string text,bool error=false){footer.Text=text;footer.ForeColor=error?Theme.Amber:Theme.Green;}
    public string AccountJson(int slot){return Data.Serializer.Serialize(accounts.ContainsKey(slot)?accounts[slot]:new Dictionary<string,object>());}
    public void SelectAccount(int slot){if(slot<1||slot>4)throw new ArgumentOutOfRangeException("slot");selected=slot;overview=false;Render();}
    public SupplyForm CreateSupply(int slot){return new SupplyForm(AccountJson(slot));}
    public void ShowOverview(){overview=true;Render();}
