      bool connected=Data.S(a,"status")=="conectada", imported=Data.B(a,"imported");
      accountTitle.Text=Data.S(a,"nick","Conta "+selected);statusLabel.Text="●  "+Data.Status(a);statusLabel.ForeColor=connected?Theme.Green:Theme.Muted;Theme.StatusState(statusLabel,Data.S(a,"status"));
      string hunt=CultureInfo.GetCultureInfo("pt-BR").TextInfo.ToTitleCase(Data.S(a,"hunt","uma área do jogo").Replace('_',' '));
