      var activePokemon=Data.Get(a,"activePokemon");progressText.Text="Treinador · nível "+(Data.Get(a,"trainerLevel")==null?"—":Theme.F(Data.N(a,"trainerLevel")))+"\n\n"+(activePokemon==null?"Nenhum Pokémon em campo.":(Data.B(activePokemon,"shiny")?"★ ":"")+Data.S(activePokemon,"name")+" · nível "+(Data.Get(activePokemon,"level")==null?"—":Theme.F(Data.N(activePokemon,"level"))))+(connected?"":"\nÚltima leitura · conta parada");
