      coins.Text=Data.Get(a,"gold")==null?"—":Theme.F(Data.N(a,"gold"));gain.Text=Data.Get(a,"gain")==null?"—":(Data.N(a,"gain")>=0?"+":"")+Theme.F(Data.N(a,"gain"));gain.ForeColor=Data.N(a,"gain")<0?Theme.Red:Theme.Green;signal.Text=connected?"Online":"Pausada";
